import{courseCoordinates,localPoint}from'./traversal-layout.js';
import{movingPose,coinPose,boulderPose,gustState,thornState,crystalState,trialHint}from'./path-trials-layout.js';
import{travelState}from'./traversal.js';
export class PathTrials{
 constructor(nav){this.nav=nav;this.state=nav.state;}
 get section(){return this.nav.section;}
 record(s=this.section){if(s?.trial?.kind!=='crystals')return null;const t=travelState(this.nav.state);t.crystals??={};return t.crystals[s.trial.id]??={hp:3,broken:[]};}
 get focus(){const s=this.blocking;if(!s)return null;const p=localPoint(s,s.trial.s);return Math.hypot(p.x-this.nav.player.x,p.z-this.nav.player.z)<6?p:null;}
 get blocking(){const s=this.section;return s?.trial?.kind==='crystals'&&this.record(s).hp>0?s:null;}
 clear(p){const n=this.nav;for(const s of n.course||[]){if(s.trial?.kind==='wind')for(const cover of s.trial.covers)if(n.y<1.4&&Math.hypot(p.x-cover.x,p.z-cover.z)<cover.r+n.radius)return false;if(s.trial?.kind==='crystals'&&this.record(s).hp>0){const q=courseCoordinates(s,p);if(q.s>s.trial.s-.28-n.radius&&q.s<s.length+2&&Math.abs(q.lateral)<4)return false;}}return true;}
 aim(){const n=this.nav,s=this.blocking;if(!s)return;const r=this.record(s),available=s.trial.nodes.filter((_,i)=>!r.broken?.includes(i));const node=available.reduce((a,b)=>Math.hypot(a.x-n.player.x,a.z-n.player.z)<Math.hypot(b.x-n.player.x,b.z-n.player.z)?a:b);if(Math.hypot(node.x-n.player.x,node.z-n.player.z)<3.2+n.radius){const heading=Math.atan2(node.x-n.player.x,node.z-n.player.z);n.heading=heading;n.events.face?.(heading);}}
 canStrike(){const n=this.nav,s=this.blocking;if(!s||!crystalState(s,n.courseTime).open)return false;const r=this.record(s);return s.trial.nodes.some((p,i)=>!r.broken?.includes(i)&&Math.hypot(p.x-n.player.x,p.z-n.player.z)<2.0+n.radius);}
 strike(){const n=this.nav,s=this.blocking;if(!s)return false;const r=this.record(s),index=s.trial.nodes.findIndex((p,i)=>!r.broken?.includes(i)&&Math.hypot(p.x-n.player.x,p.z-n.player.z)<2.0+n.radius),node=s.trial.nodes[index];if(!node)return false;return this.strikeNode(index);}
 strikeNode(index){const n=this.nav,s=this.blocking;if(!s)return false;const r=this.record(s),node=s.trial.nodes[index];if(!node||r.broken?.includes(index))return false;const open=crystalState(s,n.courseTime).open;if(open){r.hp--;r.broken??=[];r.broken.push(index);n.events.trialSave?.();if(r.hp===0)n.events.trialReward?.(s);n.events.impact?.({...node,y:.9},true);}else n.events.impact?.({...node,y:.9},false);return true;}
 carry(oldTime,newTime){const n=this.nav;if(!n.grounded)return;for(const s of n.course||[])if(s.trial?.kind==='moving')for(const p of s.platforms){if(!p.motion)continue;const old=movingPose(s,p,oldTime);if(Math.abs(n.y-p.y)<.035&&Math.hypot(n.player.x-old.x,n.player.z-old.z)<p.r-Math.min(.18,n.radius*.23)){const next=movingPose(s,p,newTime),x=n.player.x+next.x-old.x,z=n.player.z+next.z-old.z;if(n.clear(x,z)){n.player={x,z};n.passiveCarry=true;}return;}}}
 safe(){const n=this.nav;for(const s of n.course||[]){const q=courseCoordinates(s,n.player),t=s.trial;if(!t||q.s<2||q.s>s.length-2)continue;if(t.kind==='boulders'&&!t.shelters.some(p=>Math.hypot(n.player.x-p.x,n.player.z-p.z)<.70))return false;if(t.kind==='thorns'&&t.rows.some(row=>Math.abs(q.s-row.s)<1.4))return false;if(t.kind==='moving'&&!s.platforms.some(p=>!p.motion&&Math.abs(n.y-p.y)<.04&&Math.hypot(n.player.x-p.x,n.player.z-p.z)<p.r-.2))return false;if(t.kind==='wind'&&!t.covers.some(c=>q.s<c.s-.3&&q.s>c.s-2.7&&Math.abs(q.lateral-c.lateral)<1))return false;}return true;}
 step(dt){const n=this.nav;for(const s of n.course||[]){const t=s.trial;if(!t)continue;const q=courseCoordinates(s,n.player);if(q.s<1||q.s>s.length-1||Math.abs(q.lateral)>3.4)continue;
  if(t.kind==='boulders'&&n.invincible<=0){for(const lane of t.lanes){const b=boulderPose(s,lane,n.courseTime);if(b.visible&&n.y<1.3&&Math.hypot(n.player.x-b.x,n.player.z-b.z)<lane.r+n.radius*.60){n.retry('boulder');return;}}}
  if(t.kind==='thorns'&&n.invincible<=0&&n.y<.72){for(const row of t.rows){if(Math.abs(q.s-row.s)>.35+n.radius*.4)continue;const phase=thornState(row,n.courseTime);if(Math.abs(q.lateral-phase.gap)>row.gapWidth/2-n.radius*.5){n.retry('thorns');return;}}}
  if(t.kind==='wind'){const g=gustState(s,n.courseTime),sheltered=t.covers.some(c=>q.s<c.s-.25&&q.s>c.s-2.7&&Math.abs(q.lateral-c.lateral)<1.0);if(g.active&&!sheltered){const back=n.jumping?-3.8:-3.1,side=s.area>0?g.sign*.65:0,x=n.player.x+(s.forward.x*back+s.right.x*side)*dt,z=n.player.z+(s.forward.z*back+s.right.z*side)*dt;if(n.clear(x,z))n.player={x,z};}}
 }
 }
}
export function validTrials(e){if(e.adventureVersion!==undefined&&![0,1].includes(e.adventureVersion))return false;if(e.legacyThrough!==undefined&&(!Number.isInteger(e.legacyThrough)||e.legacyThrough< -1||e.legacyThrough>20))return false;const crystals=e.travel?.crystals;return crystals===undefined||!!crystals&&typeof crystals==='object'&&!Array.isArray(crystals)&&Object.keys(crystals).length<=2&&Object.entries(crystals).every(([id,r])=>id.startsWith(e.id+':travel:')&&id.endsWith(':crystals')&&r&&Number.isInteger(r.hp)&&r.hp>=0&&r.hp<=3&&(r.broken===undefined||Array.isArray(r.broken)&&r.broken.length===3-r.hp&&new Set(r.broken).size===r.broken.length&&r.broken.every(i=>Number.isInteger(i)&&i>=0&&i<3))); }
